parameters.jsCode:
// Parse AI Sales Intelligence response safely
let sales = {};

try {
  sales = JSON.parse($json.output);
} catch (error) {
  sales = {
    lead_score: 0,
    lead_temperature: "Unknown",
    sales_priority: "Unknown",
    conversion_probability: "Unknown",
    response_time: "Unknown",
    opportunity_level: "Unknown",
    sales_recommendation: "Unknown",
    follow_up_required: false
  };
}

// Get data from the previous Qualification Code Node
const lead = $('Code').first().json;

// Return merged object
return {
  // Existing Lead Information
  response_id: lead.response_id,
  lead_id: lead.lead_id,
  name: lead.name,
  email: lead.email,
  message: lead.message,

  // Qualification Information
  lead_summary: lead.lead_summary,
  intent: lead.intent,
  category: lead.category,
  pain_point: lead.pain_point,
  urgency: lead.urgency,
  sentiment: lead.sentiment,
  confidence: lead.confidence,
  qualification_status: lead.qualification_status,
  next_action: lead.next_action,

  // Sales Intelligence
  lead_score: sales.lead_score,
  lead_temperature: sales.lead_temperature,
  sales_priority: sales.sales_priority,
  conversion_probability: sales.conversion_probability,
  response_time: sales.response_time,
  opportunity_level: sales.opportunity_level,
  sales_recommendation: sales.sales_recommendation,
  follow_up_required: sales.follow_up_required,

  // Workflow Metadata
  status: "Sales Ready",
  created_at: lead.created_at,
  updated_at: new Date().toISOString()
};

// ========================================
// AI CRM & Follow-up Automation
// Part 4 - Production Version
// ========================================

// Clone incoming lead data
const lead = { ...$json };

// Current date
const today = new Date();
const followUpDate = new Date(today);

// Default CRM values
let crmStatus = "Pending Review";
let assignedTo = "Sales Queue";
let lastAction = "CRM Record Created";
let notificationRequired = false;

// ========================================
// CRM BUSINESS LOGIC
// ========================================

switch (lead.sales_priority) {

  case "High":
    crmStatus = "Pending Contact";
    assignedTo = "Sales Team";
    followUpDate.setDate(today.getDate()); // Today
    notificationRequired = true;
    break;

  case "Medium":
    crmStatus = "Follow-up Scheduled";
    assignedTo = "Sales Queue";
    followUpDate.setDate(today.getDate() + 1); // Tomorrow
    notificationRequired = true;
    break;

  case "Low":
    crmStatus = "Lead Nurturing";
    assignedTo = "Marketing Queue";
    followUpDate.setDate(today.getDate() + 3);
    notificationRequired = false;
    break;

  default:
    crmStatus = "Pending Review";
    assignedTo = "Sales Queue";
    followUpDate.setDate(today.getDate() + 2);
    notificationRequired = false;
}

// ========================================
// FOLLOW-UP CHECK
// ========================================

if (lead.follow_up_required === false) {
  crmStatus = "No Follow-up Required";
  notificationRequired = false;
}

// ========================================
// INTERNAL CRM NOTES
// ========================================

const internalNotes =
`Lead Summary: ${lead.lead_summary}

Intent: ${lead.intent}
Category: ${lead.category}

Lead Score: ${lead.lead_score}
Lead Temperature: ${lead.lead_temperature}

Sales Priority: ${lead.sales_priority}
Opportunity Level: ${lead.opportunity_level}

Recommendation: ${lead.sales_recommendation}

Follow-up Required: ${lead.follow_up_required ? "Yes" : "No"}`;

// ========================================
// RETURN FINAL CRM RECORD
// ========================================

return {

  // Existing Lead Information
  ...lead,

  // CRM Automation
  crm_status: crmStatus,
  assigned_to: assignedTo,
  follow_up_date: followUpDate.toISOString().split("T")[0],
  last_action: lastAction,
  internal_notes: internalNotes,
  notification_required: notificationRequired,

  // Workflow Status
  status: "CRM Updated",
  crm_updated_at: new Date().toISOString()

};

